/* Black Label (KURO) select screen data (bl_select_data.c, generated by research/phase20/make_select_data.py --long) */
struct sel_sprite {
	u8 page, px, py, pw, ph; /* our texture page and rectangle (screen orientation) */
};
/* An element of a state, sampled every 2 frames from the state's entry: samples seq .. seq + intro - 1 play once,
 * then seq + intro .. + loop - 1 repeat (loop 32 = 64 frames, 1 = constant, 0 = gone after the intro). */
struct sel_track {
	u16 sprite, seq;
	s16 x, y;      /* game coordinates (blitter op position minus the screen origin) of its first appearance */
	u8 intro, loop;
};
struct sel_rec {
	s16 dx, dy;    /* from the track's position */
	u8 flags, tint; /* sel_flags / sel_tints index; flags 255 = not drawn */
};
enum { SEL_HEAD, SEL_JOIN_P2, SEL_SHIP_S, SEL_SHIP_P, SEL_TYPE_S, SEL_TYPE_P = SEL_TYPE_S + 4, SEL_SHIP_S2 = SEL_TYPE_P + 4,
       SEL_SHIP_P2, SEL_TYPE_S2, SEL_TYPE_P2 = SEL_TYPE_S2 + 4, SEL_OPEN = SEL_TYPE_P2 + 4, SEL_OPEN2,
       SEL_STATES };
extern const struct sel_sprite sel_sprites[];
extern const struct sel_track sel_tracks[];
extern const u16 sel_state_refs[];
extern const u16 sel_state_first[SEL_STATES + 1];
extern const u16 sel_state_ship[SEL_STATES];
extern const struct sel_rec sel_recs[];
extern const u16 sel_samples[];
extern const u32 sel_flags[], sel_tints[];
extern const u8 sel_digit_sprite[10];
extern const u32 sel_digit_flags, sel_digit_tint;
